class Solution:
    def earliestFullBloom(self, plantTime: List[int], growTime: List[int]) -> int:
        indices = list(range(len(plantTime)))
        indices.sort(key=lambda i: growTime[i], reverse=True)
        curr_day = 0
        max_bloom = 0
        for i in indices:
            curr_day += plantTime[i]
            max_bloom = max(max_bloom, curr_day + growTime[i])
        return max_bloom

class Solution {
public:
    int earliestFullBloom(vector<int>& plantTime, vector<int>& growTime) {
        int n = plantTime.size();
        vector<int> indices(n);
        iota(indices.begin(), indices.end(), 0);
        sort(indices.begin(), indices.end(), [&](int a, int b) {
            return growTime[a] > growTime[b];
        });
        int currDay = 0, maxBloom = 0;
        for (int i : indices) {
            currDay += plantTime[i];
            maxBloom = max(maxBloom, currDay + growTime[i]);
        }
        return maxBloom;
    }
};

class Solution {
    public int earliestFullBloom(int[] plantTime, int[] growTime) {
        int n = plantTime.length;
        Integer[] indices = new Integer[n];
        for (int i = 0; i < n; i++) indices[i] = i;
        Arrays.sort(indices, (a, b) -> Integer.compare(growTime[b], growTime[a]));
        int currDay = 0, maxBloom = 0;
        for (int i : indices) {
            currDay += plantTime[i];
            maxBloom = Math.max(maxBloom, currDay + growTime[i]);
        }
        return maxBloom;
    }
}

var earliestFullBloom = function(plantTime, growTime) {
    const n = plantTime.length;
    const indices = Array.from({ length: n }, (_, i) => i);
    indices.sort((a, b) => growTime[b] - growTime[a]);
    let currDay = 0, maxBloom = 0;
    for (const i of indices) {
        currDay += plantTime[i];
        maxBloom = Math.max(maxBloom, currDay + growTime[i]);
    }
    return maxBloom;
};
